const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v₀ = 0（由静止释放）' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W * 0.48;
    var cy = H * 0.30;
    var yEnd = H * 0.86;
    var r = Math.max(10, Math.min(W, H) * 0.045);
    if (r > (yEnd - cy) / 4) { r = Math.max(8, (yEnd - cy) / 4); }

    var trail = [['M', cx, cy + r], ['L', cx, yEnd]];
    var ball = visualSdk.circle(cx, cy, r);

    var room = yEnd - cy - r - 10;
    var L = Math.min(H * 0.18, Math.max(40, room));
    var off = r + Math.max(34, W * 0.08);
    var vx = cx + off;
    var gx = cx - off;
    var y0 = cy - r * 0.5;
    var y1 = y0 + L;
    var head = Math.max(9, L * 0.3);

    var vArrow = [
      ['M', vx, y0], ['L', vx, y1],
      ['M', vx - head * 0.55, y1 - head], ['L', vx, y1],
      ['L', vx + head * 0.55, y1 - head]
    ];
    var gArrow = [
      ['M', gx, y0], ['L', gx, y1],
      ['M', gx - head * 0.55, y1 - head], ['L', gx, y1],
      ['L', gx + head * 0.55, y1 - head]
    ];

    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'trail', commands: trail },
        { id: 'ball', commands: ball },
        { id: 'vArrow', commands: vArrow },
        { id: 'gArrow', commands: gArrow }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'trail', fill: '#9aa7b8', stroke: { width: 2, cap: 'round', dash: [6, 6] } },
          { type: 'path', pathId: 'ball', fill: '#26354a', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'vArrow', fill: '#1f6feb', stroke: { width: 2.4, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'gArrow', fill: '#c0392b', stroke: { width: 2.4, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: vx + 12, y: y0 + L * 0.5 }, hAlign: 'left', vAlign: 'middle', color: '#1f6feb' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: gx - 12, y: y0 + L * 0.5 }, hAlign: 'right', vAlign: 'middle', color: '#c0392b' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: cx, y: cy - r - 14 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' }
        ]
      }
    };
  }
};
